# ============================================================
# ФУНКЦИИ
# ============================================================

def clamp(value, minimum, maximum):
    return max(minimum, min(value, maximum))


def distance(a, b):
    return math.hypot(
        a[0] - b[0],
        a[1] - b[1]
    )


def angle_difference(target, current):
    return (
        target - current + math.pi
    ) % (math.pi * 2) - math.pi


def rotate_point(px, py, angle):
    return (
        px * math.cos(angle) - py * math.sin(angle),
        px * math.sin(angle) + py * math.cos(angle)
    )


def draw_text(text, x, y, color=WHITE, used_font=None):

    if used_font is None:
        used_font = font

    image = used_font.render(
        text,
        True,
        color
    )

    screen.blit(
        image,
        (int(x), int(y))
    )


def draw_centered(text, x, y, color=WHITE, used_font=None):

    if used_font is None:
        used_font = font

    image = used_font.render(
        text,
        True,
        color
    )

    screen.blit(
        image,
        (
            int(x - image.get_width() / 2),
            int(y)
        )
    )


def draw_panel(rect, color=(20, 39, 46), border=GOLD):
    rect = pygame.Rect(rect)
    pygame.draw.rect(screen, (9, 22, 28), rect.move(4, 5), border_radius=9)
    pygame.draw.rect(screen, color, rect, border_radius=9)
    pygame.draw.rect(screen, border, rect, 2, border_radius=9)
    if rect.width > 20 and rect.height > 20:
        pygame.draw.line(screen, (112, 99, 70),
                         (rect.left+10, rect.top+5), (rect.right-10, rect.top+5))


