class Particle:

    def __init__(
        self,
        x,
        y,
        dx,
        dy,
        life,
        color,
        size,
        kind="circle"
    ):

        self.x = x
        self.y = y

        self.dx = dx
        self.dy = dy

        self.life = life
        self.max_life = life

        self.color = color
        self.size = size

        self.kind = kind

    def update(self, dt):

        self.x += self.dx * dt
        self.y += self.dy * dt

        self.dx *= 0.985
        self.dy *= 0.985

        self.life -= dt

    def draw(self, camera):

        if self.life <= 0:
            return

        sx, sy = camera.world_to_screen(
            self.x,
            self.y
        )

        ratio = self.life / self.max_life

        size = max(
            1,
            int(self.size * ratio)
        )

        if self.kind == "wood":

            pygame.draw.line(
                screen,
                self.color,
                (
                    int(sx - size),
                    int(sy - size)
                ),
                (
                    int(sx + size),
                    int(sy + size)
                ),
                2
            )

        else:

            pygame.draw.circle(
                screen,
                self.color,
                (
                    int(sx),
                    int(sy)
                ),
                size
            )


# ============================================================
# ВЕТЕР
# ============================================================

class Wind:

    def __init__(self):

        self.angle = random.uniform(
            0,
            math.pi * 2
        )

        self.strength = 0.75

        self.target_angle = self.angle
        self.target_strength = self.strength

        self.change_timer = 18

    def update(self, dt):

        self.change_timer -= dt

        if self.change_timer <= 0:

            self.change_timer = random.uniform(
                15,
                30
            )

            self.target_angle += random.uniform(
                -math.radians(60),
                math.radians(60)
            )

            self.target_angle %= (
                math.pi * 2
            )

            self.target_strength = random.uniform(
                0.55,
                1.0
            )

        diff = angle_difference(
            self.target_angle,
            self.angle
        )

        self.angle += (
            diff * dt * 0.08
        )

        self.angle %= (
            math.pi * 2
        )

        self.strength += (
            self.target_strength
            - self.strength
        ) * dt * 0.08

    def efficiency(self, ship_angle):

        diff = abs(
            angle_difference(
                self.angle,
                ship_angle
            )
        )

        deg = math.degrees(diff)

        if deg <= 30:
            value = 1.00

        elif deg <= 60:
            value = 0.90

        elif deg <= 100:
            value = 0.75

        elif deg <= 130:
            value = 0.52

        elif deg <= 155:
            value = 0.32

        else:
            value = 0.12

        return value * (
            0.55
            + self.strength * 0.45
        )

    def description(self, ship_angle):

        diff = abs(
            angle_difference(
                self.angle,
                ship_angle
            )
        )

        deg = math.degrees(diff)

        if deg <= 30:
            return "ПОПУТНЫЙ"

        if deg <= 60:
            return "ХОРОШИЙ"

        if deg <= 100:
            return "БОКОВОЙ"

        if deg <= 130:
            return "ВСТРЕЧНЫЙ"

        if deg <= 155:
            return "ПЛОХОЙ"

        return "ПРОТИВ ВЕТРА"


