class Camera:

    def __init__(self):

        self.x = 0
        self.y = 0

    def update(self, x, y):

        self.x = clamp(
            x - WIDTH / 2,
            0,
            WORLD_WIDTH - WIDTH
        )

        self.y = clamp(
            y - HEIGHT / 2,
            0,
            WORLD_HEIGHT - HEIGHT
        )

    def world_to_screen(self, x, y):

        return (
            x - self.x,
            y - self.y
        )


