def rig_ship(hull, faction, level):
    """Compose three readable sail states without changing ship physics."""
    ship = pygame.transform.smoothscale(hull, (192, 258))
    if faction == "ghost":
        ship.fill((90, 220, 190, 210), special_flags=pygame.BLEND_RGBA_MULT)
    cloth = {"player": (246, 226, 182), "trader": (224, 229, 204),
             "pirate": (65, 59, 56), "ghost": (91, 196, 163)}[faction]
    shade = {"player": (191, 163, 117), "trader": (152, 177, 161),
             "pirate": (37, 36, 38), "ghost": (39, 109, 99)}[faction]
    for y, width in ((70, 56), (126, 72), (182, 58)):
        pygame.draw.line(ship, (63, 39, 27), (96, y-25), (96, y+30), 4)
        pygame.draw.line(ship, (189, 139, 76), (97, y-24), (97, y+29), 1)
        for sign in (-1, 1):
            pygame.draw.line(ship, (77, 66, 48), (96, y-20),
                             (96+sign*width//2, y+25), 1)
        depth = (5, 16, 30)[level-1]
        points = [(96-width//2, y), (96+width//2, y),
                  (96+width//2-4, y+depth), (96, y+depth+5),
                  (96-width//2+4, y+depth)]
        pygame.draw.polygon(ship, shade, points)
        pygame.draw.polygon(ship, cloth, [(x, yy-2) for x, yy in points])
        pygame.draw.lines(ship, (113, 93, 66), False, points[1:], 1)
        for offset in (-width//4, 0, width//4):
            pygame.draw.line(ship, shade, (96+offset, y+2),
                             (96+int(offset*.85), y+depth-2), 1)
        pygame.draw.line(ship, (69, 45, 28), (96-width//2-4, y-2),
                         (96+width//2+4, y-2), 3)
    flag = {"player": (185, 49, 44), "pirate": (30, 31, 35),
            "trader": (46, 125, 151), "ghost": (64, 232, 192)}[faction]
    pygame.draw.polygon(ship, flag, [(97, 41), (122, 45), (119, 56), (97, 52)])
    if faction == "pirate":
        pygame.draw.circle(ship, (237, 221, 184), (109, 48), 3)
    return ship


def ocean_tile():
    """Периодическая вода: мягкие глубины, рябь и светлые гребни."""
    size = 512
    tile = pygame.Surface((size, size)).convert()
    for y in range(size):
        for x in range(size):
            u, v = x*math.tau/size, y*math.tau/size
            swell = (math.sin(u*2+v*3)*.5+math.cos(u*3-v*2)*.45+
                     math.sin(u*5-v*4)*.2+math.cos(u*7+v*5)*.12)
            warp = math.sin(u*3-v*2)*2+math.cos(u*2+v*3)*2
            ripple = math.sin(u*13+v*9+warp)*math.cos(u*7-v*11+warp)*.8
            crest = max(0, ripple-.48)
            grain = math.sin(u*39+v*27)*math.cos(u*23-v*31)*1.5
            tile.set_at((x, y), (int(13+5*swell+35*crest+grain),
                                int(103+12*swell+44*crest+grain),
                                int(124+11*swell+36*crest+grain)))
    return tile


def water_highlights(surface, camera, seconds):
    width, height = surface.get_size()
    spacing = 92
    for wx in range(math.floor(camera.x/spacing)*spacing,
                    int(camera.x+width)+spacing, spacing):
        for wy in range(math.floor(camera.y/spacing)*spacing,
                        int(camera.y+height)+spacing, spacing):
            seed = math.sin(wx*12.9898+wy*78.233)*43758.5453
            jitter = seed-math.floor(seed)
            phase = wx*.017+wy*.023+seconds*.8+jitter*math.tau
            sx = int(wx-camera.x+jitter*35+math.sin(phase)*13)
            sy = int(wy-camera.y+jitter*27+math.cos(phase)*6)
            light = (math.sin(phase)+1)*.5
            color = (int(56+light*68), int(157+light*50), int(165+light*42))
            points = [(sx+i, sy+int(math.sin(i*.13+phase)*2))
                      for i in range(0, 37, 4)]
            pygame.draw.aalines(surface, color, False, points)
            if light > .94:
                pygame.draw.line(surface, (246, 222, 169), (sx+12, sy-2),
                                 (sx+18, sy-2), 1)


