def get_sprite(name):
    if name in _SPRITES:
        return _SPRITES[name]
    # Новое оформление встроено в файл; прежние PNG остаются резервом.
    if name.startswith("ship_") and name.endswith(("_1.png", "_2.png", "_3.png")):
        faction = name.split("_")[1]
        if faction in ("player", "pirate", "trader", "ghost"):
            hull = get_sprite("painted_hull.png")
            if hull is not None:
                _SPRITES[name] = rig_ship(hull, faction, int(name[-5]))
                return _SPRITES[name]
    if name == "painted_hull.png":
        import io
        try:
            raw = base64.b64decode(_PAINTED_HULL_DATA)
            _SPRITES[name] = pygame.image.load(io.BytesIO(raw), name).convert_alpha()
        except (pygame.error, ValueError):
            _SPRITES[name] = None
        return _SPRITES[name]
    path = os.path.join(os.path.dirname(os.path.abspath(__file__)), "groza_sprites", name)
    try:
        _SPRITES[name] = pygame.image.load(path).convert_alpha()
    except (pygame.error, FileNotFoundError):
        try:
            import io
            raw = base64.b64decode(_EMBEDDED_SPRITES[name])
            _SPRITES[name] = pygame.image.load(io.BytesIO(raw), name).convert_alpha()
        except (KeyError, pygame.error, ValueError):
            _SPRITES[name] = None
    return _SPRITES[name]

def draw_ship_sprite(camera, x, y, angle, scale, name):
    source = get_sprite(name)
    if source is None:
        return False
    degrees = round((-math.degrees(angle)-90)/3)*3
    size = max(1, round(scale*100))
    key = (name, degrees, size)
    if key not in _ROTATED:
        if len(_ROTATED) >= 450:
            _ROTATED.clear()
            _SHIP_SHADOWS.clear()
        small = pygame.transform.smoothscale(source,
                    (max(1, int(82*scale)), max(1, int(110*scale))))
        image = pygame.transform.rotate(small, degrees)
        _ROTATED[key] = image
        shadow = image.copy()
        shadow.fill((8, 35, 41, 95), special_flags=pygame.BLEND_RGBA_MULT)
        _SHIP_SHADOWS[key] = shadow
    sx, sy = camera.world_to_screen(x, y)
    image = _ROTATED[key]
    rect = image.get_rect(center=(int(sx), int(sy)))
    screen.blit(_SHIP_SHADOWS[key], rect.move(4, 6))
    screen.blit(image, rect)
    return True

class Building:

    def __init__(
        self,
        x,
        y,
        w,
        h,
        name,
        color
    ):

        self.rect = pygame.Rect(
            x,
            y,
            w,
            h
        )

        self.name = name
        self.color = color

    def draw(self):
        sprite_names = {
            "Таверна": "tavern.png",
            "Банк": "bank.png",
            "Магазин": "shop.png",
            "Верфь": "shipyard.png"
        }
        sprite = get_sprite(sprite_names.get(self.name, "house.png"))
        if sprite:
            w,h=self.rect.width+30,self.rect.height+40
            key=(sprite_names.get(self.name,"house.png"),w,h)
            if not hasattr(self,"building_sprite"):
                self.building_sprite=pygame.transform.smoothscale(sprite,(w,h))
            screen.blit(self.building_sprite,(self.rect.x-15,self.rect.y-28))
            draw_centered(self.name,self.rect.centerx,self.rect.y+77,
                          WHITE,small_font)
            return

        # тень
        shadow = self.rect.move(
            7,
            7
        )

        pygame.draw.rect(
            screen,
            (95, 78, 60),
            shadow,
            border_radius=5
        )

        # стены
        pygame.draw.rect(
            screen,
            self.color,
            self.rect,
            border_radius=5
        )

        # деревянные балки
        pygame.draw.line(
            screen,
            DARK_BROWN,
            (
                self.rect.x + 12,
                self.rect.y
            ),
            (
                self.rect.x + 12,
                self.rect.bottom
            ),
            5
        )

        pygame.draw.line(
            screen,
            DARK_BROWN,
            (
                self.rect.right - 12,
                self.rect.y
            ),
            (
                self.rect.right - 12,
                self.rect.bottom
            ),
            5
        )

        # крыша
        pygame.draw.polygon(
            screen,
            DARK_BROWN,
            [
                (
                    self.rect.x - 12,
                    self.rect.y + 5
                ),
                (
                    self.rect.centerx,
                    self.rect.y - 35
                ),
                (
                    self.rect.right + 12,
                    self.rect.y + 5
                )
            ]
        )

        # дверь
        pygame.draw.rect(
            screen,
            BROWN,
            (
                self.rect.centerx - 14,
                self.rect.bottom - 42,
                28,
                42
            )
        )

        # окна
        for wx in (
            self.rect.x + 30,
            self.rect.right - 55
        ):

            pygame.draw.rect(
                screen,
                LIGHT_BLUE,
                (
                    wx,
                    self.rect.y + 42,
                    25,
                    24
                )
            )

            pygame.draw.line(
                screen,
                WHITE,
                (
                    wx + 12,
                    self.rect.y + 42
                ),
                (
                    wx + 12,
                    self.rect.y + 66
                ),
                2
            )

        draw_centered(
            self.name,
            self.rect.centerx,
            self.rect.y + 77,
            WHITE,
            small_font
        )


