class Cannonball:

    def __init__(
        self,
        x,
        y,
        angle,
        owner,
        damage
    ):

        self.x = x
        self.y = y

        self.speed = 420

        self.dx = (
            math.cos(angle)
            * self.speed
        )

        self.dy = (
            math.sin(angle)
            * self.speed
        )

        self.owner = owner
        self.damage = damage

        self.life = 2.2
        self.travelled = 0.0
        self.max_range = 160.0

    def update(self, dt):

        self.x += self.dx * dt
        self.y += self.dy * dt
        self.travelled += self.speed * dt
        if self.travelled >= self.max_range:
            self.life = 0

        self.life -= dt

    def draw(self, camera):

        sx, sy = camera.world_to_screen(
            self.x,
            self.y
        )

        # маленькая тень
        pygame.draw.circle(
            screen,
            SEA_DARK,
            (
                int(sx + 3),
                int(sy + 4)
            ),
            5
        )

        pygame.draw.circle(
            screen,
            BLACK,
            (
                int(sx),
                int(sy)
            ),
            5
        )

        pygame.draw.circle(
            screen,
            GRAY,
            (
                int(sx - 1),
                int(sy - 1)
            ),
            2
        )


