class Loot:

    def __init__(self, x, y):

        self.x = x
        self.y = y

        self.gold = random.randint(
            20,
            70
        )

        self.ammo = random.randint(
            3,
            10
        )

        self.materials = {k: 0 for k in RESOURCE_KEYS}
        self.life = 45

    def update(self, dt):
        self.life -= dt

    def draw(self, camera):

        sx, sy = camera.world_to_screen(
            self.x,
            self.y
        )

        pygame.draw.rect(
            screen,
            DARK_BROWN,
            (
                int(sx - 11),
                int(sy - 8),
                22,
                16
            ),
            border_radius=3
        )

        pygame.draw.rect(
            screen,
            GOLD,
            (
                int(sx - 11),
                int(sy - 8),
                22,
                16
            ),
            2,
            border_radius=3
        )

        pygame.draw.line(
            screen,
            GOLD,
            (
                int(sx),
                int(sy - 7)
            ),
            (
                int(sx),
                int(sy + 7)
            ),
            2
        )


