# ФИЗИКА КОРАБЛЕЙ
# ============================================================

class ShipPhysics:

    def __init__(
        self,
        x,
        y,
        cannon_count
    ):

        self.x = x
        self.y = y

        self.angle = -math.pi / 2

        self.speed = 0

        self.cannon_count = cannon_count

        # Физика столкновений
        self.collision_radius = 34 + min(cannon_count, 20) * 0.45
        self.collision_cooldown = 0.0

    def ship_mass(self):

        # Больше пушек — тяжелее корабль и сильнее таран.
        return 1.0 + self.cannon_count * 0.075

    def velocity(self):

        return (
            math.cos(self.angle) * self.speed,
            math.sin(self.angle) * self.speed
        )

    def calculate_base_speed(self):

        return clamp(
            106 - self.cannon_count * 3,
            45,
            100
        )

    def calculate_acceleration(self):

        return clamp(
            48 - self.cannon_count * 0.8,
            22,
            46
        )

    def calculate_rotation(self):

        return clamp(
            1.35 - self.cannon_count * 0.025,
            0.65,
            1.25
        )

    def wind_speed(self, wind):

        return (
            self.calculate_base_speed()
            * wind.efficiency(
                self.angle
            )
        )


# ============================================================
# РИСОВАНИЕ КОРАБЛЯ
# ============================================================

def draw_detailed_ship(
    camera,
    x,
    y,
    angle,
    cannon_count,
    hull_color,
    sail_color,
    flag_color,
    scale=1.0,
    speed=0.0
):

    sprite_name = ("ship_ghost.png" if flag_color == GHOST_CYAN
                   else "ship_player.png" if flag_color == RED
                   else "ship_pirate.png" if flag_color == BLACK
                   else "ship_trader.png")
    sail_level = 1 if abs(speed) < 14 else (2 if abs(speed) < 48 else 3)
    sprite_name = sprite_name.replace(".png", f"_{sail_level}.png")
    if draw_ship_sprite(camera,x,y,angle,scale,sprite_name):
        return

    sx, sy = camera.world_to_screen(
        x,
        y
    )

    def transform(px, py):

        rx, ry = rotate_point(
            px * scale,
            py * scale,
            angle
        )

        return (
            sx + rx,
            sy + ry
        )

    # ========================================================
    # ТЕНЬ
    # ========================================================

    shadow_points = []

    for p in [
        (38, 4),
        (22, 20),
        (-30, 18),
        (-43, 4),
        (-30, -10),
        (22, -12)
    ]:

        px, py = transform(
            p[0] + 5,
            p[1] + 5
        )

        shadow_points.append(
            (px, py)
        )

    pygame.draw.polygon(
        screen,
        SEA_DARK,
        shadow_points
    )

    # ========================================================
    # КОРПУС
    # ========================================================

    hull = []

    for p in [
        (42, 0),
        (25, 18),
        (-28, 17),
        (-43, 0),
        (-28, -17),
        (25, -18)
    ]:

        hull.append(
            transform(
                p[0],
                p[1]
            )
        )

    pygame.draw.polygon(
        screen,
        hull_color,
        hull
    )

    pygame.draw.polygon(
        screen,
        BLACK,
        hull,
        2
    )

    # ========================================================
    # ПАЛУБА
    # ========================================================

    deck = []

    for p in [
        (27, 0),
        (16, 11),
        (-24, 10),
        (-31, 0),
        (-24, -10),
        (16, -11)
    ]:

        deck.append(
            transform(
                p[0],
                p[1]
            )
        )

    pygame.draw.polygon(
        screen,
        LIGHT_WOOD,
        deck
    )

    # продольные доски
    for offset in [-5, 0, 5]:

        p1 = transform(
            -22,
            offset
        )

        p2 = transform(
            22,
            offset
        )

        pygame.draw.line(
            screen,
            BROWN,
            p1,
            p2,
            1
        )

    # ========================================================
    # ПУШКИ
    # ========================================================

    guns_side = min(
        cannon_count // 2,
        6
    )

    if guns_side > 0:

        for i in range(guns_side):

            position = (
                -18
                + i * (
                    34 / max(
                        1,
                        guns_side - 1
                    )
                )
                if guns_side > 1
                else 0
            )

            for side in [-1, 1]:

                base = transform(
                    position,
                    side * 14
                )

                end = transform(
                    position,
                    side * 21
                )

                pygame.draw.line(
                    screen,
                    BLACK,
                    base,
                    end,
                    max(
                        2,
                        int(3 * scale)
                    )
                )

    # ========================================================
    # МАЧТА
    # ========================================================

    mast_back = transform(
        -5,
        0
    )

    mast_front = transform(
        16,
        0
    )

    pygame.draw.circle(
        screen,
        DARK_BROWN,
        (
            int(mast_back[0]),
            int(mast_back[1])
        ),
        max(
            3,
            int(4 * scale)
        )
    )

    pygame.draw.circle(
        screen,
        DARK_BROWN,
        (
            int(mast_front[0]),
            int(mast_front[1])
        ),
        max(
            2,
            int(3 * scale)
        )
    )

    # ========================================================
    # ПАРУС
    #
    # Вид сверху: парус изображается
    # как светлая полоска поперёк корпуса.
    # ========================================================

    sail_a = transform(
        -7,
        -20
    )

    sail_b = transform(
        -7,
        20
    )

    pygame.draw.line(
        screen,
        DARK_BROWN,
        sail_a,
        sail_b,
        max(
            2,
            int(3 * scale)
        )
    )

    sail_points = [
        transform(-10, -18),
        transform(-2, -13),
        transform(-2, 13),
        transform(-10, 18)
    ]

    pygame.draw.polygon(
        screen,
        sail_color,
        sail_points
    )

    pygame.draw.polygon(
        screen,
        DARK_BROWN,
        sail_points,
        1
    )

    # второй парус
    sail2_points = [
        transform(12, -12),
        transform(19, -8),
        transform(19, 8),
        transform(12, 12)
    ]

    pygame.draw.polygon(
        screen,
        sail_color,
        sail2_points
    )

    # ========================================================
    # ФЛАГ НА КОРМЕ
    # ========================================================

    flag_base = transform(
        -35,
        0
    )

    flag_end = transform(
        -48,
        -8
    )

    flag_tip = transform(
        -48,
        0
    )

    pygame.draw.line(
        screen,
        BLACK,
        flag_base,
        flag_end,
        2
    )

    pygame.draw.polygon(
        screen,
        flag_color,
        [
            flag_end,
            transform(-60, -6),
            flag_tip
        ]
    )

    # носовая точка
    bow = transform(
        43,
        0
    )

    pygame.draw.circle(
        screen,
        GOLD,
        (
            int(bow[0]),
            int(bow[1])
        ),
        max(
            2,
            int(3 * scale)
        )
    )


# ============================================================
# КОРАБЛЬ ИГРОКА
# ============================================================

class PlayerShip(ShipPhysics):

    def __init__(self, x, y):

        super().__init__(
            x,
            y,
            4
        )

        self.health = 100
        self.max_health = 100

        # Раздельная перезарядка бортов
        self.left_reload = 0
        self.right_reload = 0

        self.wake_timer = 0
        self.gun_type = 1

    @property
    def damage(self):
        return 18

    @property
    def cannons_per_side(self):

        return max(
            1,
            self.cannon_count // 2
        )

    def update(
        self,
        dt,
        wind,
        particles
    ):

        keys = pygame.key.get_pressed()

        self.collision_cooldown = max(
            0.0,
            self.collision_cooldown - dt
        )

        base_speed = (
            self.calculate_base_speed()
        )

        max_wind_speed = (
            self.wind_speed(
                wind
            )
        )

        acceleration = (
            self.calculate_acceleration()
        )

        rotation = (
            self.calculate_rotation()
        )

        efficiency = (
            wind.efficiency(
                self.angle
            )
        )

        # ====================================================
        # ПАРУСА
        # ====================================================

        if keys[pygame.K_w]:

            self.speed += (
                acceleration
                * max(
                    0.20,
                    efficiency
                )
                * dt
            )

        elif keys[pygame.K_s]:

            self.speed -= (
                acceleration
                * 0.7
                * dt
            )

        else:

            self.speed *= 0.997

        # Если корабль идёт быстрее,
        # чем позволяет текущий ветер,
        # постепенно теряем скорость.
        if self.speed > max_wind_speed:

            self.speed -= (
                acceleration
                * 0.25
                * dt
            )

        self.speed = clamp(
            self.speed,
            -base_speed * 0.08,
            base_speed
        )

        # ====================================================
        # РУЛЬ
        # ====================================================

        movement_factor = clamp(
            abs(self.speed) / 22,
            0.12,
            1
        )

        if keys[pygame.K_a]:

            self.angle -= (
                rotation
                * movement_factor
                * dt
            )

        if keys[pygame.K_d]:

            self.angle += (
                rotation
                * movement_factor
                * dt
            )

        self.angle %= (
            math.pi * 2
        )

        # ====================================================
        # ДВИЖЕНИЕ
        # ====================================================

        self.x += (
            math.cos(self.angle)
            * self.speed
            * dt
        )

        self.y += (
            math.sin(self.angle)
            * self.speed
            * dt
        )

        self.x = clamp(
            self.x,
            45,
            WORLD_WIDTH - 45
        )

        self.y = clamp(
            self.y,
            45,
            WORLD_HEIGHT - 45
        )

        self.left_reload = max(
            0,
            self.left_reload - dt
        )

        self.right_reload = max(
            0,
            self.right_reload - dt
        )

        # ====================================================
        # КИЛЬВАТЕРНЫЙ СЛЕД
        # ====================================================

        if abs(self.speed) > 12:

            self.wake_timer -= dt

            if self.wake_timer <= 0:

                self.wake_timer = 0.07

                stern_x = (
                    self.x
                    - math.cos(
                        self.angle
                    ) * 36
                )

                stern_y = (
                    self.y
                    - math.sin(
                        self.angle
                    ) * 36
                )

                for side in [-1, 1]:

                    side_angle = (
                        self.angle
                        + side
                        * math.pi / 2
                    )

                    px = (
                        stern_x
                        + math.cos(
                            side_angle
                        ) * 10
                    )

                    py = (
                        stern_y
                        + math.sin(
                            side_angle
                        ) * 10
                    )

                    particles.append(
                        Particle(
                            px,
                            py,
                            -math.cos(
                                self.angle
                            ) * 8
                            + random.uniform(
                                -4,
                                4
                            ),
                            -math.sin(
                                self.angle
                            ) * 8
                            + random.uniform(
                                -4,
                                4
                            ),
                            1.2,
                            FOAM,
                            random.randint(
                                3,
                                6
                            )
                        )
                    )

    def fire(
        self,
        balls,
        particles,
        side,
        player
    ):

        if side == "left":

            if self.left_reload > 0:
                return False, "reload"

        else:

            if self.right_reload > 0:
                return False, "reload"

        count = (
            self.cannons_per_side
        )

        if player.cannonballs < count:

            return False, "ammo"

        player.cannonballs -= count

        if side == "left":

            fire_angle = (
                self.angle
                - math.pi / 2
            )

        else:

            fire_angle = (
                self.angle
                + math.pi / 2
            )

        spacing = 14

        start = -(
            (count - 1)
            * spacing
            / 2
        )

        for i in range(count):

            offset = (
                start
                + i * spacing
            )

            bx = (
                self.x
                + math.cos(
                    self.angle
                ) * offset
                + math.cos(
                    fire_angle
                ) * 20
            )

            by = (
                self.y
                + math.sin(
                    self.angle
                ) * offset
                + math.sin(
                    fire_angle
                ) * 20
            )

            shot_angle = (
                fire_angle
                + random.uniform(
                    -0.035,
                    0.035
                )
            )

            balls.append(
                Cannonball(
                    bx,
                    by,
                    shot_angle,
                    "player",
                    (28, 18, 12)[self.gun_type]
                )
            )
            balls[-1].max_range = (90, 160, 240)[self.gun_type]


            # дым
            for j in range(5):

                particles.append(
                    Particle(
                        bx,
                        by,
                        math.cos(
                            fire_angle
                        ) * random.uniform(
                            10,
                            35
                        )
                        + random.uniform(
                            -10,
                            10
                        ),
                        math.sin(
                            fire_angle
                        ) * random.uniform(
                            10,
                            35
                        )
                        + random.uniform(
                            -10,
                            10
                        ),
                        random.uniform(
                            0.5,
                            1.1
                        ),
                        SMOKE,
                        random.randint(
                            5,
                            10
                        )
                    )
                )

            # вспышка
            particles.append(
                Particle(
                    bx,
                    by,
                    math.cos(
                        fire_angle
                    ) * 15,
                    math.sin(
                        fire_angle
                    ) * 15,
                    0.18,
                    GOLD,
                    9
                )
            )

        if side == "left":

            self.left_reload = 1.7

        else:

            self.right_reload = 1.7

        return True, "ok"

    def draw(self, camera):

        # Чем больше пушек,
        # тем немного крупнее корабль.
        scale = (
            1.12
            + min(
                self.cannon_count,
                20
            ) * 0.012
        )

        draw_detailed_ship(
            camera,
            self.x,
            self.y,
            self.angle,
            self.cannon_count,
            DARK_BROWN,
            SAIL_WHITE,
            RED,
            scale,
            self.speed
        )

        sx, sy = camera.world_to_screen(
            self.x,
            self.y
        )

        # здоровье
        pygame.draw.rect(
            screen,
            BLACK,
            (
                int(sx - 35),
                int(sy - 50),
                70,
                7
            )
        )

        pygame.draw.rect(
            screen,
            RED,
            (
                int(sx - 34),
                int(sy - 49),
                68,
                5
            )
        )

        pygame.draw.rect(
            screen,
            GREEN,
            (
                int(sx - 34),
                int(sy - 49),
                int(
                    68
                    * self.health
                    / self.max_health
                ),
                5
            )
        )


# ============================================================
# NPC
# ============================================================

class NPCShip(ShipPhysics):

    def __init__(
        self,
        x,
        y,
        ship_type,
        cannon_count
    ):

        super().__init__(
            x,
            y,
            cannon_count
        )

        self.ship_type = ship_type

        self.target_x = x
        self.target_y = y

        self.reload = random.uniform(
            1,
            4
        )

        self.alive = True

        self.combat_side = random.choice(
            [-1, 1]
        )

        if ship_type == "trader":

            self.name = "Торговец"

            self.health = (
                80
                + cannon_count * 4
            )

            self.hull_color = BROWN
            self.sail_color = SAIL_WHITE
            self.flag_color = GOLD

        elif ship_type == "ghost":
            self.name = "Летучий Голландец"
            self.cannon_count = 10
            self.health = 230
            self.hull_color = (37, 80, 91)
            self.sail_color = (130, 224, 208)
            self.flag_color = GHOST_CYAN

        elif ship_type == "pirate":

            self.name = "Пират"

            self.health = (
                75
                + cannon_count * 5
            )

            self.hull_color = DARK_BROWN
            self.sail_color = SAIL_PIRATE
            self.flag_color = BLACK

        else:

            self.name = "Красный Джек"

            self.health = 220

            self.hull_color = DARK_RED
            self.sail_color = SAIL_BOSS
            self.flag_color = RED

        self.max_health = (
            self.health
        )

        self.choose_target()

    @property
    def cannons_per_side(self):

        return max(
            1,
            self.cannon_count // 2
        )

    def choose_target(self):

        self.target_x = random.randint(
            250,
            WORLD_WIDTH - 250
        )

        self.target_y = random.randint(
            250,
            WORLD_HEIGHT - 250
        )

    def fire_broadside(
        self,
        balls,
        particles,
        side
    ):

        if self.reload > 0:
            return

        if side == "left":

            fire_angle = (
                self.angle
                - math.pi / 2
            )

        else:

            fire_angle = (
                self.angle
                + math.pi / 2
            )

        count = min(
            self.cannons_per_side,
            5
        )

        spacing = 12

        start = -(
            (count - 1)
            * spacing
            / 2
        )

        for i in range(count):

            offset = (
                start
                + i * spacing
            )

            bx = (
                self.x
                + math.cos(
                    self.angle
                ) * offset
                + math.cos(
                    fire_angle
                ) * 18
            )

            by = (
                self.y
                + math.sin(
                    self.angle
                ) * offset
                + math.sin(
                    fire_angle
                ) * 18
            )

            shot_angle = (
                fire_angle
                + random.uniform(
                    -0.05,
                    0.05
                )
            )

            damage = 7

            if self.ship_type == "boss":
                damage = 10
            elif self.ship_type == "ghost":
                damage = 9

            balls.append(
                Cannonball(
                    bx,
                    by,
                    shot_angle,
                    "enemy",
                    damage
                )
            )

            for j in range(3):

                particles.append(
                    Particle(
                        bx,
                        by,
                        math.cos(
                            fire_angle
                        ) * random.uniform(
                            10,
                            25
                        )
                        + random.uniform(
                            -8,
                            8
                        ),
                        math.sin(
                            fire_angle
                        ) * random.uniform(
                            10,
                            25
                        )
                        + random.uniform(
                            -8,
                            8
                        ),
                        random.uniform(
                            0.4,
                            0.9
                        ),
                        SMOKE,
                        random.randint(
                            4,
                            8
                        )
                    )
                )

        self.reload = random.uniform(
            2.5,
            3.8
        )

    def update(
        self,
        dt,
        player_ship,
        balls,
        particles,
        wind
    ):

        if not self.alive:
            return

        self.collision_cooldown = max(
            0.0,
            self.collision_cooldown - dt
        )

        self.reload -= dt

        dx = (
            player_ship.x
            - self.x
        )

        dy = (
            player_ship.y
            - self.y
        )

        dist_player = math.hypot(
            dx,
            dy
        )

        aggressive = (
            self.ship_type
            in ("pirate", "boss", "ghost")
            and dist_player < 850
        )

        if not aggressive:

            if (
                self.ship_type == "trader"
                and dist_player < 260
            ):

                target_angle = math.atan2(
                    self.y - player_ship.y,
                    self.x - player_ship.x
                )

            else:

                if distance(
                    (
                        self.x,
                        self.y
                    ),
                    (
                        self.target_x,
                        self.target_y
                    )
                ) < 100:

                    self.choose_target()

                target_angle = math.atan2(
                    self.target_y - self.y,
                    self.target_x - self.x
                )

        else:

            angle_to_player = math.atan2(
                dy,
                dx
            )

            if dist_player > 370:

                target_angle = (
                    angle_to_player
                )

            elif dist_player < 150:

                target_angle = (
                    angle_to_player
                    + math.pi
                )

            else:

                target_angle = (
                    angle_to_player
                    + self.combat_side
                    * math.pi / 2
                )

        diff = angle_difference(
            target_angle,
            self.angle
        )

        rotation = (
            self.calculate_rotation()
        )

        self.angle += clamp(
            diff,
            -rotation * dt,
            rotation * dt
        )

        self.angle %= (
            math.pi * 2
        )

        max_speed = (
            self.wind_speed(
                wind
            )
        )

        wanted_speed = (
            max_speed * 0.84
        )

        if aggressive:

            wanted_speed = (
                max_speed * 0.95
            )

        acceleration = (
            self.calculate_acceleration()
        )

        if self.speed < wanted_speed:

            self.speed += (
                acceleration * dt
            )

        else:

            self.speed -= (
                acceleration
                * 0.3
                * dt
            )

        self.speed = clamp(
            self.speed,
            0,
            self.calculate_base_speed()
        )

        self.x += (
            math.cos(
                self.angle
            )
            * self.speed
            * dt
        )

        self.y += (
            math.sin(
                self.angle
            )
            * self.speed
            * dt
        )

        self.x = clamp(
            self.x,
            45,
            WORLD_WIDTH - 45
        )

        self.y = clamp(
            self.y,
            45,
            WORLD_HEIGHT - 45
        )

        # стрельба
        if (
            aggressive
            and dist_player < 430
            and self.reload <= 0
        ):

            angle_to_player = math.atan2(
                player_ship.y - self.y,
                player_ship.x - self.x
            )

            left_angle = (
                self.angle
                - math.pi / 2
            )

            right_angle = (
                self.angle
                + math.pi / 2
            )

            left_error = abs(
                angle_difference(
                    angle_to_player,
                    left_angle
                )
            )

            right_error = abs(
                angle_difference(
                    angle_to_player,
                    right_angle
                )
            )

            firing_arc = math.radians(
                30
            )

            if left_error < firing_arc:

                self.fire_broadside(
                    balls,
                    particles,
                    "left"
                )

            elif right_error < firing_arc:

                self.fire_broadside(
                    balls,
                    particles,
                    "right"
                )

    def draw(self, camera):

        sx, sy = camera.world_to_screen(
            self.x,
            self.y
        )

        if (
            sx < -100
            or sx > screen.get_width() + 100
            or sy < -100
            or sy > screen.get_height() + 100
        ):
            return

        scale = 0.95

        if self.ship_type == "boss":
            scale = 1.28
        elif self.ship_type == "ghost":
            scale = 1.18
            haze = pygame.Surface((128,128),pygame.SRCALPHA)
            for rad in range(58,10,-8):
                pygame.draw.circle(haze,(36,190,192,7),(64,64),rad)
            screen.blit(haze,(int(sx)-64,int(sy)-64))

        draw_detailed_ship(
            camera,
            self.x,
            self.y,
            self.angle,
            self.cannon_count,
            self.hull_color,
            self.sail_color,
            self.flag_color,
            scale,
            self.speed
        )

        # здоровье
        width = 54

        if self.ship_type in ("boss", "ghost"):
            width = 75

        pygame.draw.rect(
            screen,
            BLACK,
            (
                int(sx - width / 2),
                int(sy - 48),
                width,
                6
            )
        )

        pygame.draw.rect(
            screen,
            GREEN,
            (
                int(sx - width / 2 + 1),
                int(sy - 47),
                int(
                    (width - 2)
                    * self.health
                    / self.max_health
                ),
                4
            )
        )

        if self.ship_type == "ghost":
            draw_centered("КОРАБЛЬ-ПРИЗРАК",sx,sy-72,GHOST_CYAN,tiny_font)
        if self.ship_type == "boss":

            draw_centered(
                "КРАСНЫЙ ДЖЕК",
                sx,
                sy - 68,
                GOLD,
                tiny_font
            )


