class IslandColony:
    def __init__(self, island):
        self.name = island.name
        self.owner = ("player" if island.name == "Порт-Ройал"
                      else "pirate" if island.name in ("Тортуга", "Остров Черепа")
                      else "neutral")
        self.zones = {
            name: {"active": False, "pending": 0, "timer": 0.0}
            for name in ISLAND_RESOURCES.get(island.name, ("wood",))
        }
        self.stock = {k: 0 for k in RESOURCE_KEYS}
        self.house = False
        self.worker = False
        self.shipyard = False
        self.market = (island.name == "Порт-Ройал")
        self.fort = 1 if self.owner == "pirate" else 0
        self.fort_hp = 90 if self.owner == "pirate" else 0
        self.cannons = 1 if self.owner == "pirate" else 0
        self.fort_reload = 3.5
        self.worker_timer = 0.0

    def tick(self, dt):
        if self.owner != "player":
            return
        for name, zone in self.zones.items():
            if not zone["active"]:
                continue
            zone["timer"] += dt
            if zone["pending"] < RESOURCE_CAP[name]:
                n = int(zone["timer"] / RESOURCE_PERIODS[name])
                if n:
                    added = min(n, RESOURCE_CAP[name] - zone["pending"])
                    zone["pending"] += added
                    zone["timer"] %= RESOURCE_PERIODS[name]
            else:
                zone["timer"] = min(zone["timer"], RESOURCE_PERIODS[name])
        if self.worker:
            self.worker_timer += dt
            if self.worker_timer >= 5:
                self.worker_timer %= 5
                for name, zone in self.zones.items():
                    self.stock[name] += zone["pending"]
                    zone["pending"] = 0

    def serialize(self):
        return {"owner": self.owner, "zones": self.zones,
                "stock": self.stock, "house": self.house, "worker": self.worker,
                "shipyard": self.shipyard, "market": self.market,
                "fort": self.fort,
                "fort_hp": self.fort_hp, "cannons": self.cannons}

    def restore(self, data):
        if not isinstance(data, dict):
            return
        if data.get("owner") in FACTION_COLORS:
            self.owner = data["owner"]
        for name, zone in self.zones.items():
            raw = data.get("zones", {}).get(name, {})
            zone["active"] = bool(raw.get("active", False))
            zone["pending"] = max(0, min(RESOURCE_CAP[name], int(raw.get("pending", 0))))
            zone["timer"] = max(0, float(raw.get("timer", 0)))
        for k in RESOURCE_KEYS:
            self.stock[k] = max(0, int(data.get("stock", {}).get(k, 0)))
        self.house = bool(data.get("house", False))
        self.worker = bool(data.get("worker", False)) and self.house
        self.shipyard = bool(data.get("shipyard", False))
        self.market = bool(data.get("market", self.market))
        self.fort = max(0, min(3, int(data.get("fort", 0))))
        self.fort_hp = max(0, float(data.get("fort_hp", 0)))
        self.cannons = max(0, min(6, int(data.get("cannons", 0))))

class ColonyTrader:
    """Автономный торговый корабль, рейсы на главный остров и обратно."""
    def __init__(self, home, capital, first_load=True):
        self.home = home
        self.capital = capital
        self.x = home.x + home.radius + 145
        self.y = home.y
        self.health = 95.0
        self.max_health = 95.0
        self.phase = "to_capital"
        self.cargo = {k: 0 for k in RESOURCE_KEYS}
        self.reload = 0.0
        self.alive = True
        self.speed = 85.0
        self.angle = 0

    def serialize(self):
        return {"home": self.home.name, "x": self.x, "y": self.y,
                "health": self.health, "phase": self.phase,
                "cargo": self.cargo}

    def restore(self, data):
        self.x = float(data.get("x", self.x))
        self.y = float(data.get("y", self.y))
        self.health = max(1, float(data.get("health", 95)))
        self.phase = data.get("phase", "to_capital")
        if self.phase not in ("to_capital", "to_home"):
            self.phase = "to_capital"
        self.cargo = {k: max(0, int(data.get("cargo", {}).get(k, 0)))
                      for k in RESOURCE_KEYS}

