    def colony(self, island=None):
        island = island or self.colony_island
        return self.colonies[island.name] if island is not None else None

    def resource_text(self, amounts):
        return "  ".join(f"{RESOURCE_NAMES[k]}: {amounts.get(k, 0)}"
                         for k in RESOURCE_KEYS)

    def accessible_materials(self, colony):
        # Личные запасы доступны везде, на захваченном острове — местный склад.
        return {k: self.resources[k] + colony.stock[k] for k in RESOURCE_KEYS}

    def pay_materials(self, colony, price):
        available = self.accessible_materials(colony)
        if any(available[k] < amount for k, amount in price.items()):
            missing = [f"{RESOURCE_NAMES[k]} {amount-available[k]}"
                       for k, amount in price.items() if amount > available[k]]
            self.show_message("Не хватает: " + ", ".join(missing), 4)
            return False
        for k, amount in price.items():
            local = min(colony.stock[k], amount)
            colony.stock[k] -= local
            self.resources[k] -= amount-local
        return True

    def find_landing(self):
        """Ближайший доступный берег — учёт эллиптической формы острова."""
        best, best_ratio = None, float('inf')
        for island in self.islands:
            dx = self.ship.x-island.x
            dy = self.ship.y-island.y
            ratio = math.hypot(dx/(island.radius+65),
                               dy/(island.radius*.65+65))
            if ratio < best_ratio:
                best, best_ratio = island, ratio
        return best if best_ratio < 1.8 else None

    def land_on_island(self, island, return_mode="sea"):
        colony = self.colony(island)
        if colony.owner == "pirate" and colony.fort_hp > 0:
            self.show_message("Берег занят пиратами! Разрушьте крепость ядрами.", 5)
            return
        if return_mode == "sea" and abs(self.ship.speed) > 25:
            self.show_message("Снизьте скорость для высадки (до 25).")
            return
        self.colony_island = island
        self.colony_return = return_mode
        self.player.x = WIDTH//2-13
        self.player.y = HEIGHT-155
        self.mode = "island"
        self.ship.speed = 0
        self.sound.play_music("city")
        self.show_message("Высадка: " + island.name + ". Подойдите к участку и нажмите E.", 4)

    def enter_nearby_island(self):
        island = self.find_landing()
        if island:
            self.land_on_island(island)
        else:
            self.show_message("Для высадки подойдите ближе к берегу.")

    def island_nodes(self):
        col = self.colony()
        coords = [(295, 275), (790, 275)]
        return [(name, coords[i][0], coords[i][1])
                for i, name in enumerate(col.zones)]

    def island_interact(self):
        col = self.colony()
        px = self.player.x+self.player.w/2
        py = self.player.y+self.player.h/2
        for name, x, y in self.island_nodes():
            if math.hypot(px-x, py-y) > 90:
                continue
            if col.owner != "player":
                self.show_message("Сначала захватите остров клавишей C.")
                return
            z = col.zones[name]
            if not z["active"]:
                z["active"] = True
                self.show_message(f"{RESOURCE_NAMES[name]}: добыча запущена!", 4)
            elif z["pending"]:
                count = z["pending"]
                self.resources[name] += count
                z["pending"] = 0
                self.show_message(f"Собрано: {RESOURCE_NAMES[name]} +{count}", 4)
            else:
                self.show_message("Запас пока пуст. Подождите производства.")
            return
        self.show_message("Подойдите к шахте, лесу или пастбищу и нажмите E.")

    def capture_island(self):
        col = self.colony()
        if col.owner == "player":
            self.show_message("Этот остров уже ваш.")
        elif col.owner == "pirate" and col.fort_hp > 0:
            self.show_message("Сначала уничтожьте пиратскую крепость с корабля.", 4)
        elif self.player.gold < 70:
            self.show_message("Для захвата нужен гарнизон: 70 золотых.")
        else:
            self.player.gold -= 70
            col.owner = "player"
            col.fort = 0
            col.fort_hp = 0
            col.cannons = 0
            self.show_message("Остров захвачен! Теперь активируйте месторождения.", 5)

    def build_colony(self, option):
        col = self.colony()
        if col.owner != "player":
            self.show_message("Этот остров не принадлежит вам.")
            return
        names = {"house": "Дом работника", "fort": "Укрепление",
                 "cannon": "Береговая пушка", "shipyard": "Верфь",
                 "trader": "Торговое судно", "market": "Рынок"}
        cost = BUILD_PRICES[option]
        if option == "house" and col.house:
            self.show_message("Дом уже построен.")
            return
        if option == "shipyard" and col.shipyard:
            self.show_message("Верфь уже построена.")
            return
        if option == "market" and col.market:
            self.show_message("Рынок уже построен.")
            return
        if option == "fort" and col.fort >= 3:
            self.show_message("Укрепление достигло максимального уровня.")
            return
        if option == "cannon" and (col.fort < 1 or col.cannons >= 6):
            self.show_message("Сначала постройте укрепление (макс. 6 пушек).")
            return
        if option == "trader":
            if not col.shipyard:
                self.show_message("Сначала постройте верфь.")
                return
            if self.colony_island.name == self.capital_name:
                self.show_message("Торговые рейсы строятся на других островах.")
                return
            if sum(s.alive and s.home.name == self.colony_island.name
                   for s in self.colony_ships) >= 3:
                self.show_message("Предел: 3 торговых судна на остров.")
                return
        if not self.pay_materials(col, cost):
            return
        if option == "house":
            col.house = True
            col.worker = True
        elif option == "fort":
            col.fort += 1
            col.fort_hp = col.fort*120
        elif option == "cannon":
            col.cannons += 1
        elif option == "shipyard":
            col.shipyard = True
        elif option == "market":
            col.market = True
        elif option == "trader":
            ship = ColonyTrader(self.colony_island, self.islands[0])
            self.load_trader(ship)
            self.colony_ships.append(ship)
        self.show_message(names[option] + " — построено!", 4)

    def load_trader(self, ship):
        col = self.colony(ship.home)
        for k in RESOURCE_KEYS:
            n = min(18, col.stock[k])
            col.stock[k] -= n
            ship.cargo[k] = n

    def add_ship_wreck(self, ship):
        crate = Loot(ship.x, ship.y)
        if getattr(ship, 'ship_type', None) == 'ghost':
            crate.gold=180
            crate.ammo=12
            crate.materials={"wood":8,"stone":8,"wool":8}
        if getattr(ship, 'ship_type', None) == 'trader':
            # У каждого купца разный груз; есть также смешанные грузы.
            types = random.sample(RESOURCE_KEYS, random.choice((1, 1, 2, 3)))
            crate.materials = {k: (random.randint(3, 13) if k in types else 0)
                               for k in RESOURCE_KEYS}
        self.loot.append(crate)

    def update_colonies(self, dt):
        self.colony_time += dt
        for island in self.islands:
            col = self.colony(island)
            col.tick(dt)
            col.fort_reload -= dt
            if col.cannons and col.fort_hp > 0 and col.fort_reload <= 0:
                px = island.x + island.radius*.5
                py = island.y-island.radius*.12
                if col.owner == "player":
                    threats = [npc for npc in self.npc_ships if npc.alive and
                               npc.ship_type in ('pirate', 'boss', 'ghost') and
                               math.hypot(npc.x-px, npc.y-py)<380]
                    if threats:
                        enemy = min(threats, key=lambda n: math.hypot(n.x-px,n.y-py))
                        enemy.health -= 9+col.cannons*11
                        self.colony_trails.append([px,py,enemy.x,enemy.y,0.32])
                        col.fort_reload = max(1.2, 5-col.cannons*.5)
                        if enemy.health <= 0:
                            enemy.alive = False
                            self.add_ship_wreck(enemy)
                            if enemy.ship_type == 'boss':
                                self.boss_killed = True
                                self.quest_active = False
                elif col.owner == "pirate":
                    if math.hypot(self.ship.x-px, self.ship.y-py)<320:
                        self.ship.health -= 8+col.cannons*6
                        self.colony_trails.append([px,py,self.ship.x,self.ship.y,0.3])
                        col.fort_reload = 5.0
        for trail in self.colony_trails[:]:
            trail[4] -= dt
            if trail[4] <= 0:
                self.colony_trails.remove(trail)

        pirates = [n for n in self.npc_ships if n.alive and n.ship_type in ('pirate','boss','ghost')]
        for trader in self.colony_ships[:]:
            if not trader.alive:
                continue
            target = (trader.capital if trader.phase == 'to_capital'
                      else trader.home)
            tx = target.x+target.radius+160
            ty = target.y
            dx,dy=tx-trader.x,ty-trader.y
            dist=math.hypot(dx,dy)
            step=min(dist, trader.speed*dt)
            if dist > 0.001:
                trader.x += dx/dist*step
                trader.y += dy/dist*step
                trader.angle = math.atan2(dy,dx)
            if dist <= 10:
                if trader.phase == 'to_capital':
                    capital=self.colony(trader.capital)
                    for k,n in trader.cargo.items():
                        capital.stock[k]+=n
                    trader.cargo={k:0 for k in RESOURCE_KEYS}
                    trader.phase='to_home'
                    self.show_message('Торговое судно доставило ресурсы в столицу.',3)
                else:
                    trader.phase='to_capital'
                    self.load_trader(trader)
                    trader.health=min(trader.max_health,trader.health+12)
            trader.reload-=dt
            enemy = next((pirate for pirate in pirates
                          if math.hypot(pirate.x-trader.x,pirate.y-trader.y)<170),None)
            if enemy and trader.reload <= 0:
                trader.health-=random.randint(13,24)
                trader.reload=3.2
                self.colony_trails.append([enemy.x,enemy.y,trader.x,trader.y,0.26])
            if trader.health <= 0:
                trader.alive=False
                crate=Loot(trader.x,trader.y)
                crate.materials=trader.cargo.copy()
                crate.gold=0
                crate.ammo=0
                self.loot.append(crate)
                self.show_message('Пираты потопили ваш торговый корабль!',4)
        # NPC-пираты стремятся к проходящим торговым кораблям.
        if pirates and self.colony_ships and random.random()<dt*.25:
            targets=[t for t in self.colony_ships if t.alive]
            if targets:
                t=random.choice(targets)
                near=min(pirates,key=lambda n:math.hypot(n.x-t.x,n.y-t.y))
                if math.hypot(near.x-t.x,near.y-t.y)<750:
                    near.target_x,near.target_y=t.x,t.y

    def draw_trade_ships(self):
        for t in self.colony_ships:
            if not t.alive:
                continue
            x,y=self.camera.world_to_screen(t.x,t.y)
            if x < -100 or x > screen.get_width()+100 or y < -100 or y > screen.get_height()+100:
                continue
            a=t.angle
            dx,dy=math.cos(a),math.sin(a)
            side=(-dy,dx)
            shape=[(x+dx*24,y+dy*24),
                   (x+side[0]*11-dx*15,y+side[1]*11-dy*15),
                   (x-side[0]*11-dx*15,y-side[1]*11-dy*15)]
            pygame.draw.polygon(screen,(100,65,40),shape)
            pygame.draw.polygon(screen,(57,142,210),shape,2)  # синий флаг игрока
            pygame.draw.line(screen,(232,219,183),(int(x),int(y)),
                             (int(x+side[0]*8),int(y+side[1]*8)),5)
            pygame.draw.circle(screen,(252,194,79),(int(x),int(y)),3)
        for x1,y1,x2,y2,life in self.colony_trails:
            sx,sy=self.camera.world_to_screen(x1,y1)
            ex,ey=self.camera.world_to_screen(x2,y2)
            pygame.draw.line(screen,(250,193,90),(int(sx),int(sy)),(int(ex),int(ey)),2)

