    MARKET_PAIRS = (
        ("wood", "stone"), ("wood", "wool"),
        ("stone", "wood"), ("stone", "wool"),
        ("wool", "wood"), ("wool", "stone")
    )

    def market_trade(self, from_key, to_key):
        """Exchange 5 units for 1 unit. Spend island stock first if on an island."""
        col = (self.colony() if self.market_from_island else
               self.colony(self.islands[0]))
        available = self.resources[from_key] + col.stock[from_key]
        if available < 5:
            self.show_message("Для обмена нужно 5 единиц: " + RESOURCE_NAMES[from_key], 4)
            return False
        stock_spent = min(col.stock[from_key], 5)
        col.stock[from_key] -= stock_spent
        self.resources[from_key] -= 5-stock_spent
        self.resources[to_key] += 1
        self.show_message("Обмен: -5 " + RESOURCE_NAMES[from_key] +
                          ", +1 " + RESOURCE_NAMES[to_key], 3)
        return True

    def draw_market(self):
        title = "РЫНОК ОСТРОВА" if self.market_from_island else "РЫНОК ПОРТ-РОЙАЛА"
        self.draw_room_art("РЫНОК")
        self.draw_hud()
        draw_centered(title, WIDTH//2, 94, GOLD, big_font)
        draw_panel(pygame.Rect(165, 147, 770, 440), (49, 43, 36), LIGHT_WOOD)
        msg = small_font.render("Курс: отдаёте 5 единиц одного ресурса — получаете 1 другого",True,GOLD)
        screen.blit(msg,(205,169))
        for i,(source,target) in enumerate(self.MARKET_PAIRS):
            x = 215 + (i%2)*370
            y = 225 + (i//2)*100
            draw_text(f"[{i+1}]", x, y, WHITE, font)
            draw_resource_icon(screen,source,x+72,y+11,27)
            draw_text("5",x+95,y,WHITE,font)
            draw_text("→",x+135,y,GOLD,font)
            draw_resource_icon(screen,target,x+198,y+11,27)
            draw_text("1",x+222,y,WHITE,font)
        col = self.colony() if self.market_from_island else self.colony(self.islands[0])
        draw_text("При себе:",207,525,GOLD,small_font)
        draw_resource_icons_row(screen,self.resources,290,520,84)
        draw_text("На складе:",570,525,GOLD,small_font)
        draw_resource_icons_row(screen,col.stock,667,520,79)
        self.draw_bottom("1–6 — обменять ресурсы по курсу 5 к 1   ESC — назад")
        self.draw_message()

