    # ========================================================

    def draw_wind_indicator(self):

        cx = 845
        cy = 130

        radius = 47

        pygame.draw.circle(
            screen,
            (23, 42, 50),
            (
                cx,
                cy
            ),
            radius
        )

        pygame.draw.circle(
            screen,
            LIGHT_WOOD,
            (
                cx,
                cy
            ),
            radius,
            3
        )

        # деления компаса
        for i in range(8):

            a = (
                i
                * math.pi
                / 4
            )

            x1 = (
                cx
                + math.cos(a)
                * 37
            )

            y1 = (
                cy
                + math.sin(a)
                * 37
            )

            x2 = (
                cx
                + math.cos(a)
                * 44
            )

            y2 = (
                cy
                + math.sin(a)
                * 44
            )

            pygame.draw.line(
                screen,
                WHITE,
                (
                    int(x1),
                    int(y1)
                ),
                (
                    int(x2),
                    int(y2)
                ),
                2
            )

        length = (
            25
            + self.wind.strength * 15
        )

        ex = (
            cx
            + math.cos(
                self.wind.angle
            ) * length
        )

        ey = (
            cy
            + math.sin(
                self.wind.angle
            ) * length
        )

        pygame.draw.line(
            screen,
            GOLD,
            (
                cx,
                cy
            ),
            (
                int(ex),
                int(ey)
            ),
            5
        )

        # стрелка
        a1 = (
            self.wind.angle
            + 2.55
        )

        a2 = (
            self.wind.angle
            - 2.55
        )

        pygame.draw.polygon(
            screen,
            GOLD,
            [
                (
                    int(ex),
                    int(ey)
                ),
                (
                    int(
                        ex
                        + math.cos(a1)
                        * 12
                    ),
                    int(
                        ey
                        + math.sin(a1)
                        * 12
                    )
                ),
                (
                    int(
                        ex
                        + math.cos(a2)
                        * 12
                    ),
                    int(
                        ey
                        + math.sin(a2)
                        * 12
                    )
                )
            ]
        )

        draw_centered(
            "ВЕТЕР",
            cx,
            73,
            WHITE,
            tiny_font
        )

        draw_centered(
            f"{int(self.wind.strength * 100)}%",
            cx,
            181,
            WHITE,
            tiny_font
        )

