    # МИНИ-КАРТА
    # ========================================================

    def draw_minimap(self):

        map_w = 190
        map_h = 175

        map_x = (
            WIDTH
            - map_w
            - 15
        )

        map_y = 220

        pygame.draw.rect(
            screen,
            (12, 62, 86),
            (
                map_x,
                map_y,
                map_w,
                map_h
            ),
            border_radius=5
        )

        pygame.draw.rect(
            screen,
            LIGHT_WOOD,
            (
                map_x,
                map_y,
                map_w,
                map_h
            ),
            2,
            border_radius=5
        )

        for island in self.islands:

            mx = (
                map_x
                + island.x
                / WORLD_WIDTH
                * map_w
            )

            my = (
                map_y
                + island.y
                / WORLD_HEIGHT
                * map_h
            )

            pygame.draw.circle(
                screen,
                SAND,
                (
                    int(mx),
                    int(my)
                ),
                4
            )

        for npc in self.npc_ships:

            if not npc.alive:
                continue

            mx = (
                map_x
                + npc.x
                / WORLD_WIDTH
                * map_w
            )

            my = (
                map_y
                + npc.y
                / WORLD_HEIGHT
                * map_h
            )

            if npc.ship_type == "trader":
                color = WHITE

            elif npc.ship_type == "pirate":
                color = RED

            else:
                color = GOLD

            pygame.draw.circle(
                screen,
                color,
                (
                    int(mx),
                    int(my)
                ),
                2
            )

        px = (
            map_x
            + self.ship.x
            / WORLD_WIDTH
            * map_w
        )

        py = (
            map_y
            + self.ship.y
            / WORLD_HEIGHT
            * map_h
        )

        pygame.draw.circle(
            screen,
            GREEN,
            (
                int(px),
                int(py)
            ),
            5
        )

        draw_text(
            "КАРТА",
            map_x + 7,
            map_y + 5,
            WHITE,
            tiny_font
        )

